}

module.exports = { composeAsyncMiddleware };

problems.solutionCode:
function composeAsyncMiddleware(middlewares) {
  return function(context) {
    let lastIndex = -1;

    function dispatch(i) {
      if (i <= lastIndex) {
        return Promise.reject(new Error('next() called multiple times'));
      }
      lastIndex = i;
      const fn = middlewares[i];
      if (!fn) {
        return Promise.resolve();
      }
      try {
        return Promise.resolve(fn(context, () => dispatch(i + 1)));
      } catch (err) {
        return Promise.reject(err);
      }
    }

    return dispatch(0);
  };
}

module.exports = { composeAsyncMiddleware };

visibleTests.testCode:
const executionLog = [];
const m1 = async (ctx, next) => {
  executionLog.push('m1_enter');
  ctx.state += ':m1';
  await next();
  executionLog.push('m1_exit');
};
const m2 = async (ctx, next) => {
  executionLog.push('m2_enter');
  ctx.state += ':m2';
  await next();
  executionLog.push('m2_exit');
};
const pipeline = composeAsyncMiddleware([m1, m2]);
const ctx = { state: 'init' };
await pipeline(ctx);
assert.strictEqual(ctx.state, 'init:m1:m2');
assert.deepStrictEqual(executionLog, ['m1_enter', 'm2_enter', 'm2_exit', 'm1_exit']);

const badMiddleware = async (ctx, next) => {
  await next();
  await next(); // Illegal second call
};
const pipeline = composeAsyncMiddleware([badMiddleware]);
await assert.rejects(async () => pipeline({}), /next\(\) called multiple times/);

hiddenTests.testCode:
let caughtError = null;
const errorHandler = async (ctx, next) => {
  try { await next(); } catch (err) { caughtError = err.message; }
};
const crasher = async () => { throw new Error('Database connection failed'); };
const pipeline = composeAsyncMiddleware([errorHandler, crasher]);
await pipeline({});
assert.strictEqual(caughtError, 'Database connection failed');
